CROP={"S06_C11":"crop=1102:620:89:100,scale=1280:720:flags=lanczos"}
def pre(c):
    f=[]
    for (x,y,w,h,en) in LOGO.get(c,[]): f.append(f"delogo=x={x}:y={y}:w={w}:h={h}"+(f":enable='{en}'" if en else ""))
    if c in CROP: f.append(CROP[c])
    if c in BARS:
        m=BARS[c]+3; h=(720-2*m)//2*2; w=int(h*16/9)//2*2
        f.append(f"crop={w}:{h}:{(1280-w)//2}:{m},scale=1280:720:flags=lanczos")
    return ",".join(f)
